#include "KS/SRC/custom_stl.h"

class element;
class event;
typedef list<element *> element_list_t;
typedef list<event *> event_list_t;

class element_manager {
public:
  static element_manager *inst();
  void remove_element(element *e);
};

struct rectf { float x0, y0, x1, y1; };
struct color { float r, g, b, a; };

class element
{
public:
  virtual ~element();
  void event_flush();
  virtual void render() = 0;
protected:
  element *parent;
  int type;
  unsigned int flags;
  element_list_t subelements;
  rectf subrect;
  float R[2][2];
  float T[2];
  float S[2];
  float S_Override[2];
  float O[2];
  float angle;
  color mycolor[4];
  event_list_t event_run_list;
  bool linear_animation;
};

element::~element()
{
  if ( parent )
    parent->subelements.remove( this );
  else
    element_manager::inst()->remove_element( this );

  event_flush();
  while( subelements.size() )
    delete *subelements.begin();
}
